import React from "react";

function UserList({ users }) {
  const getRoleColor = (role) => {
    switch (role) {
      case "admin": return "text-red-600 font-semibold";
      case "editor": return "text-blue-600";
      case "viewer": return "text-gray-600";
      default: return "text-gray-500";
    }
  };

  const getRoleIcon = (role) => {
    switch (role) {
      case "admin": return "👑";
      case "editor": return "✏️";
      case "viewer": return "👁️";
      default: return "👤";
    }
  };

  return (
    <div className="w-64 bg-gray-50 border-l border-gray-200 p-4">
      <h2 className="text-lg font-bold mb-4 text-gray-800 border-b pb-2">
        👥 Connected Users ({users.length})
      </h2>
      
      {users.length === 0 ? (
        <div className="text-gray-500 text-center py-8">
          <div className="text-4xl mb-2">👤</div>
          <p>No users connected</p>
        </div>
      ) : (
        <ul className="space-y-3">
          {users.map((user) => (
            <li key={user.id} className="flex items-center space-x-3 p-3 bg-white rounded-lg shadow-sm border border-gray-100">
              <div className="text-2xl">{getRoleIcon(user.role)}</div>
              <div className="flex-1">
                <div className="font-medium text-gray-900">{user.username}</div>
                <div className={`text-sm ${getRoleColor(user.role)}`}>
                  {user.role.charAt(0).toUpperCase() + user.role.slice(1)}
                </div>
              </div>
              <div className="w-3 h-3 bg-green-400 rounded-full animate-pulse"></div>
            </li>
          ))}
        </ul>
      )}
      
      <div className="mt-6 p-3 bg-blue-50 border border-blue-200 rounded-lg">
        <div className="text-sm text-blue-800">
          <div className="font-medium mb-1">Role Permissions:</div>
          <div className="text-xs space-y-1">
            <div>👑 <strong>Admin:</strong> Full control + clear board</div>
            <div>✏️ <strong>Editor:</strong> Can draw and erase</div>
            <div>👁️ <strong>Viewer:</strong> Read-only access</div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default UserList;
